-- Jalankan sekali pada Supabase SQL Editor, untuk proyek Supabase BARU.
create extension if not exists pgcrypto;
create table public.branches(id bigint generated by default as identity primary key,name text not null unique,is_active boolean not null default true);
insert into public.branches(name) values ('Tipar Cakung'),('THB Bekasi'),('Tambun Selatan'),('BKT Jakarta Timur'),('Depok'),('Karawaci Tangerang'),('Cikarang'),('Sumur Batu Jakarta Pusat'),('Depok Sport');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,role text not null default 'kasir' check(role in ('admin_pusat','kepala_cabang','kasir','mekanik','purchasing')),branch_id bigint references public.branches(id),can_access_parts boolean not null default false,is_active boolean not null default true);
create table public.employees(id bigint generated by default as identity primary key,branch_id bigint not null references public.branches(id),employee_code text not null,name text not null,position text not null,phone text,hire_date date,is_active boolean not null default true,exit_date date,exit_reason text,created_at timestamptz default now(),unique(branch_id,employee_code));
create table public.attendance(id bigint generated by default as identity primary key,employee_id bigint not null references public.employees(id),branch_id bigint not null references public.branches(id),work_date date not null,check_in timestamptz,check_out timestamptz,status text not null default 'hadir',latitude numeric(10,7),longitude numeric(10,7),selfie_path text,created_at timestamptz default now(),unique(employee_id,work_date));
create table public.parts(id bigint generated by default as identity primary key,branch_id bigint not null references public.branches(id),sku text not null,name text not null,category text,purchase_price numeric(14,2) not null default 0,stock integer not null default 0 check(stock>=0),min_stock integer not null default 0,created_at timestamptz default now(),unique(branch_id,sku));
create table public.stock_movements(id bigint generated by default as identity primary key,part_id bigint references public.parts(id),branch_id bigint references public.branches(id),movement_type text not null,quantity integer not null,notes text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.stock_transfers(id bigint generated by default as identity primary key,from_branch_id bigint references public.branches(id),to_branch_id bigint references public.branches(id),source_part_id bigint references public.parts(id),target_part_id bigint references public.parts(id),quantity integer not null,status text default 'selesai',created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.purchase_requests(id bigint generated by default as identity primary key,branch_id bigint not null references public.branches(id),part_name text not null,quantity integer not null,estimated_price numeric(14,2) default 0,reason text,status text not null default 'menunggu',requested_by uuid references auth.users(id),reviewed_by uuid references auth.users(id),created_at timestamptz default now());
create table public.services(id bigint generated by default as identity primary key,branch_id bigint not null references public.branches(id),service_date timestamptz not null default now(),customer_name text not null,phone text,plate_number text not null,motorcycle text not null,service_type text not null,mechanic_name text not null,labor_cost numeric(14,2) default 0,parts_cost numeric(14,2) default 0,notes text,created_by uuid references auth.users(id),warranty_period text default 'tanpa_garansi',mechanic_notes text,mechanic_advice text,discount numeric(14,2) default 0,total_price numeric(14,2) default 0,cashier_id uuid references auth.users(id));
create index on public.services(plate_number);
create table public.service_items(id bigint generated by default as identity primary key,service_id bigint not null references public.services(id) on delete cascade,item_type text not null,item_name text not null,quantity integer not null default 1,unit_price numeric(14,2) not null default 0,line_total numeric(14,2) not null default 0);
create table public.service_media(id bigint generated by default as identity primary key,service_id bigint not null references public.services(id) on delete cascade,phase text not null,media_type text not null,file_path text not null,uploaded_at timestamptz default now());
create table public.vouchers(id bigint generated by default as identity primary key,code text not null unique,branch_id bigint references public.branches(id),discount_amount numeric(14,2) not null default 50000,customer_name text,plate_number text,issued_at timestamptz default now(),expires_at timestamptz not null default (now()+interval '30 days'),status text not null default 'aktif',used_service_id bigint references public.services(id),used_by uuid references auth.users(id),used_at timestamptz,created_by uuid references auth.users(id),cancelled_by uuid references auth.users(id),cancelled_at timestamptz,deleted_at timestamptz);
create table public.user_audit_logs(id bigint generated by default as identity primary key,user_id uuid references auth.users(id),target_type text,target_id text,action text,detail text,created_at timestamptz default now());
create or replace function public.my_role() returns text language sql stable security definer set search_path='' as $$select role from public.profiles where id=(select auth.uid()) and is_active=true$$;
create or replace function public.my_branch() returns bigint language sql stable security definer set search_path='' as $$select branch_id from public.profiles where id=(select auth.uid()) and is_active=true$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select coalesce(public.my_role()='admin_pusat',false)$$;
create or replace function public.has_parts() returns boolean language sql stable security definer set search_path='' as $$select coalesce(public.is_admin() or public.my_role()='purchasing' or (select can_access_parts from public.profiles where id=(select auth.uid())),false)$$;
create or replace function public.can_branch(b bigint) returns boolean language sql stable security definer set search_path='' as $$select coalesce(public.is_admin() or (public.my_role() is not null and b=public.my_branch()),false)$$;
alter table public.branches enable row level security;
alter table public.profiles enable row level security;
create policy branches_read on public.branches for select to authenticated using (public.my_role() is not null);
create policy branches_admin on public.branches for insert to authenticated with check(public.is_admin());
create policy profiles_read on public.profiles for select to authenticated using (id=(select auth.uid()) or public.is_admin());
create policy profiles_admin_insert on public.profiles for insert to authenticated with check(public.is_admin());
create policy profiles_admin_update on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
-- Data tiap cabang dilindungi RLS; izin insert/update diperiksa ulang oleh database.
do $$declare t text;begin foreach t in array array['employees','attendance','parts','stock_movements','stock_transfers','purchase_requests','services','service_items','service_media','vouchers','user_audit_logs'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy employees_read on public.employees for select to authenticated using(public.can_branch(branch_id));
create policy employees_insert on public.employees for insert to authenticated with check(public.can_branch(branch_id));
create policy employees_update on public.employees for update to authenticated using(public.can_branch(branch_id)) with check(public.can_branch(branch_id));
create policy attendance_read on public.attendance for select to authenticated using(public.can_branch(branch_id));
create policy attendance_insert on public.attendance for insert to authenticated with check(public.can_branch(branch_id) and exists(select 1 from public.employees e where e.id=employee_id and e.branch_id=attendance.branch_id));
create policy attendance_update on public.attendance for update to authenticated using(public.can_branch(branch_id)) with check(public.can_branch(branch_id));
create policy parts_read on public.parts for select to authenticated using(public.has_parts() and public.can_branch(branch_id));
create policy parts_insert on public.parts for insert to authenticated with check(public.has_parts() and public.can_branch(branch_id));
create policy parts_update on public.parts for update to authenticated using(public.has_parts() and public.can_branch(branch_id)) with check(public.has_parts() and public.can_branch(branch_id));
create policy movements_read on public.stock_movements for select to authenticated using(public.has_parts() and public.can_branch(branch_id));
create policy transfers_read on public.stock_transfers for select to authenticated using(public.has_parts() and (public.can_branch(from_branch_id) or public.can_branch(to_branch_id)));
create policy purchasing_read on public.purchase_requests for select to authenticated using(public.has_parts() and public.can_branch(branch_id));
create policy purchasing_insert on public.purchase_requests for insert to authenticated with check(public.has_parts() and public.can_branch(branch_id) and requested_by=(select auth.uid()));
create policy purchasing_update on public.purchase_requests for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy services_read on public.services for select to authenticated using(public.can_branch(branch_id));
create policy services_insert on public.services for insert to authenticated with check(public.can_branch(branch_id) and created_by=(select auth.uid()));
create policy items_read on public.service_items for select to authenticated using(exists(select 1 from public.services s where s.id=service_id and public.can_branch(s.branch_id)));
create policy items_insert on public.service_items for insert to authenticated with check(exists(select 1 from public.services s where s.id=service_id and public.can_branch(s.branch_id)));
create policy media_read on public.service_media for select to authenticated using(exists(select 1 from public.services s where s.id=service_id and public.can_branch(s.branch_id)));
create policy media_insert on public.service_media for insert to authenticated with check(exists(select 1 from public.services s where s.id=service_id and public.can_branch(s.branch_id)));
create policy vouchers_read on public.vouchers for select to authenticated using(public.is_admin() or (public.my_role()='kasir' and public.can_branch(branch_id)));
create policy vouchers_admin_insert on public.vouchers for insert to authenticated with check(public.is_admin() and created_by=(select auth.uid()));
create policy vouchers_admin_update on public.vouchers for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy audit_read on public.user_audit_logs for select to authenticated using(public.is_admin());
-- RPC mutasi stok atomic untuk mencegah lost update.
create or replace function public.move_stock(p_part_id bigint,p_qty integer,p_type text,p_notes text default '') returns void language plpgsql security definer set search_path='' as $$declare v public.parts%rowtype;begin if not public.has_parts() or p_qty<1 or p_type not in ('masuk','keluar') then raise exception 'Akses atau data tidak valid';end if;select * into v from public.parts where id=p_part_id for update;if not found or not public.can_branch(v.branch_id) then raise exception 'Part tidak ditemukan';end if;if p_type='keluar' and v.stock<p_qty then raise exception 'Stok tidak cukup';end if;update public.parts set stock=stock+(case when p_type='masuk' then p_qty else -p_qty end) where id=p_part_id;insert into public.stock_movements(part_id,branch_id,movement_type,quantity,notes,created_by) values(p_part_id,v.branch_id,p_type,p_qty,p_notes,auth.uid());end$$;
create or replace function public.transfer_stock(p_part_id bigint,p_target_branch bigint,p_qty integer) returns void language plpgsql security definer set search_path='' as $$declare v public.parts%rowtype;target_id bigint;begin if not public.has_parts() or p_qty<1 then raise exception 'Akses atau jumlah tidak valid';end if;select * into v from public.parts where id=p_part_id for update;if not found or not public.can_branch(v.branch_id) or v.branch_id=p_target_branch then raise exception 'Transfer tidak valid';end if;if not exists(select 1 from public.branches where id=p_target_branch and is_active) then raise exception 'Cabang tujuan tidak valid';end if;if v.stock<p_qty then raise exception 'Stok tidak cukup';end if;update public.parts set stock=stock-p_qty where id=v.id;insert into public.parts(branch_id,sku,name,category,purchase_price,stock,min_stock) values(p_target_branch,v.sku,v.name,v.category,v.purchase_price,p_qty,v.min_stock) on conflict(branch_id,sku) do update set stock=public.parts.stock+excluded.stock returning id into target_id;insert into public.stock_movements(part_id,branch_id,movement_type,quantity,notes,created_by) values(v.id,v.branch_id,'keluar',p_qty,'Transfer cabang',auth.uid()),(target_id,p_target_branch,'masuk',p_qty,'Transfer cabang',auth.uid());insert into public.stock_transfers(from_branch_id,to_branch_id,source_part_id,target_part_id,quantity,created_by) values(v.branch_id,p_target_branch,v.id,target_id,p_qty,auth.uid());end$$;
-- RPC transaksi service dengan validasi voucher dan rincian item secara atomik.
create or replace function public.create_service(p_data jsonb,p_items jsonb default '[]'::jsonb,p_voucher text default null) returns bigint language plpgsql security definer set search_path='' as $$declare sid bigint;v public.vouchers%rowtype;labor numeric;parts numeric;disc numeric;bid bigint;item jsonb;stype text;begin bid=(p_data->>'branch_id')::bigint;if not public.can_branch(bid) then raise exception 'Cabang tidak diizinkan';end if;labor=coalesce((p_data->>'labor_cost')::numeric,0);parts=coalesce((p_data->>'parts_cost')::numeric,0);disc=coalesce((p_data->>'discount')::numeric,0);if labor<0 or parts<0 or disc<0 then raise exception 'Biaya tidak valid';end if;stype=coalesce(p_data->>'service_type','');if nullif(trim(coalesce(p_voucher,'')),'') is not null then if public.my_role()<>'kasir' then raise exception 'Voucher hanya untuk kasir';end if;select * into v from public.vouchers where code=upper(trim(p_voucher)) and status='aktif' and deleted_at is null and expires_at>=now() for update;if not found or (v.branch_id is not null and v.branch_id<>bid) then raise exception 'Voucher tidak valid';end if;if disc<>0 then raise exception 'Voucher tidak dapat digabung diskon';end if;if not (stype ilike '%rebound%' or exists(select 1 from jsonb_array_elements(p_items) i where (i->>'item_name') ilike '%rebound%' or ((i->>'item_name') ilike '%komstir%' and (i->>'item_name') ilike '%rakvs%'))) then raise exception 'Voucher hanya untuk rebound atau komstir RAKVS';end if;disc=v.discount_amount;end if;insert into public.services(branch_id,service_date,customer_name,phone,plate_number,motorcycle,service_type,mechanic_name,labor_cost,parts_cost,notes,created_by,warranty_period,mechanic_notes,mechanic_advice,discount,total_price,cashier_id) values(bid,coalesce((p_data->>'service_date')::timestamptz,now()),p_data->>'customer_name',p_data->>'phone',upper(p_data->>'plate_number'),p_data->>'motorcycle',stype,p_data->>'mechanic_name',labor,parts,p_data->>'notes',auth.uid(),coalesce(p_data->>'warranty_period','tanpa_garansi'),p_data->>'mechanic_notes',p_data->>'mechanic_advice',disc,greatest(0,labor+parts-disc),auth.uid()) returning id into sid;for item in select value from jsonb_array_elements(p_items) loop if coalesce(item->>'item_name','')<>'' then insert into public.service_items(service_id,item_type,item_name,quantity,unit_price,line_total) values(sid,item->>'item_type',item->>'item_name',greatest(1,(item->>'quantity')::integer),greatest(0,(item->>'unit_price')::numeric),greatest(1,(item->>'quantity')::integer)*greatest(0,(item->>'unit_price')::numeric));end if;end loop;if v.id is not null then update public.vouchers set status='digunakan',used_service_id=sid,used_by=auth.uid(),used_at=now(),customer_name=p_data->>'customer_name',plate_number=upper(p_data->>'plate_number') where id=v.id;end if;return sid;end$$;
create or replace function public.mark_attendance(p_employee_id bigint,p_lat numeric,p_lng numeric,p_selfie_path text default null) returns text language plpgsql security definer set search_path='' as $$declare e public.employees%rowtype;a public.attendance%rowtype;today date=(now() at time zone 'Asia/Jakarta')::date;begin select * into e from public.employees where id=p_employee_id and is_active;if not found or not public.can_branch(e.branch_id) or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'Data absensi tidak valid';end if;select * into a from public.attendance where employee_id=p_employee_id and work_date=today for update;if not found then if p_selfie_path is null then raise exception 'Selfie wajib';end if;insert into public.attendance(employee_id,branch_id,work_date,check_in,latitude,longitude,selfie_path) values(p_employee_id,e.branch_id,today,now(),p_lat,p_lng,p_selfie_path);return 'Masuk';end if;if a.check_out is not null then raise exception 'Sudah absen pulang';end if;update public.attendance set check_out=now() where id=a.id;return 'Pulang';end$$;
-- Storage privat; akses dibatasi oleh path prefix cabang / id-service atau karyawan.
insert into storage.buckets(id,name,public,file_size_limit) values('rakvs-private','rakvs-private',false,31457280) on conflict(id) do nothing;
create policy storage_read on storage.objects for select to authenticated using(bucket_id='rakvs-private' and public.my_role() is not null and (public.is_admin() or (split_part(name,'/',1)='branch' and split_part(name,'/',2)=public.my_branch()::text)));
create policy storage_insert on storage.objects for insert to authenticated with check(bucket_id='rakvs-private' and public.my_role() is not null and (public.is_admin() or (split_part(name,'/',1)='branch' and split_part(name,'/',2)=public.my_branch()::text)));
-- Buat user pertama di Supabase Authentication > Users, lalu jalankan query berikut dengan UUID-nya:
-- insert into public.profiles(id,name,role,branch_id) values('UUID-USER-ADMIN','Administrator','admin_pusat',null);
-- Akun staf berikutnya: buat di Authentication > Users, lalu tambahkan profile dengan role dan branch_id.
